n/// One request for a firm provider quote, recorded BEFORE the provider is called so retries and\n/// duplicates can never spend another provider slot. History is kept.\nmodel FirmQuoteAttempt {\n  id                     String                 @id @db.Uuid\n  paymentAuthorizationId String                 @db.Uuid\n  userId                 String                 @db.Uuid\n  walletId               String                 @db.Uuid\n  providerId             String                 @db.Uuid\n  status                 FirmQuoteAttemptStatus @default(REQUESTING)\n  idempotencyKey         String                 @unique\n  amountMode             AmountMode\n  exactAmount            String\n  exactAssetId           String                 @db.Uuid\n  takerAddress           String\n  providerQuoteId        String?\n  inputAmount            String?\n  inputAssetId           String?                @db.Uuid\n  outputAmount           String?\n  outputAssetId          String?                @db.Uuid\n  feeAmount              String?\n  feeAssetId             String?                @db.Uuid\n  reactor                String?\n  spender                String?\n  expiresAt              DateTime?              @db.Timestamptz(3)\n  orderDeadline          DateTime?              @db.Timestamptz(3)\n  latestOrderDeadline    DateTime?              @db.Timestamptz(3)\n  /// The provider's unsigned approval and swap transactions. Contains no secret.\n  unsignedTransactions   Json?\n  claimSecretId          String?                @db.Uuid\n  failureCode            String?\n  createdAt              DateTime               @default(now()) @db.Timestamptz(3)\n  updatedAt              DateTime               @updatedAt @db.Timestamptz(3)\n\n  paymentAuthorization PaymentAuthorization @relation(fields: [paymentAuthorizationId], references: [id], onDelete: Restrict)\n  user                 User                 @relation(fields: [userId], references: [id], onDelete: Cascade)\n  wallet               Wallet               @relation(fields: [walletId], references: [id], onDelete: Restrict)\n  provider             Provider             @relation(fields: [providerId], references: [id], onDelete: Restrict)\n  claimSecret          ExecutionSecret?     @relation(fields: [claimSecretId], references: [id], onDelete: Restrict)\n  exactAsset           Asset                @relation(\"FirmExactAsset\", fields: [exactAssetId], references: [id], onDelete: Restrict)\n  inputAsset           Asset?               @relation(\"FirmInputAsset\", fields: [inputAssetId], references: [id], onDelete: Restrict)\n  outputAsset          Asset?               @relation(\"FirmOutputAsset\", fields: [outputAssetId], references: [id], onDelete: Restrict)\n  feeAsset             Asset?               @relation(\"FirmFeeAsset\", fields: [feeAssetId], references: [id], onDelete: Restrict)\n  executions           Execution[]\n\n  @@index([paymentAuthorizationId, status])\n  @@index([providerId, status])\n}\n\n/// A short-lived grant to confirm ONE root (passkey) action for ONE execution: deploying the smart\n/// account and installing the restricted permission. The browser holds an opaque token; the user,\n/// wallet, execution and exact operation come from this row. The PIN is never involved.\nmodel RootActionSession {\n  id          String           @id @db.Uuid\n  userId      String           @db.Uuid\n  walletId    String           @db.Uuid\n  executionId String           @db.Uuid\n  kind        String\n  tokenHash   String?          @unique @db.Char(64)\n  status      RootActionStatus @default(PENDING)\n  /// The hash the passkey must sign (hex). Fixed by the server when the operation was prepared.\n  challenge   String\n  /// The prepared, UNSIGNED operation this session may complete. Contains no secret.\n  prepared    Json\n  expiresAt   DateTime         @db.Timestamptz(3)\n  usedAt      DateTime?        @db.Timestamptz(3)\n  createdAt   DateTime         @default(now()) @db.Timestamptz(3)\n\n  user  